query allPostsInGroup($organizationSlug: OrganizationID!, $groupId: NodeID!) {
  groupPosts(organizationId: $organizationSlug, groupId: $groupId) {
    id
    slug
    body
    createdBy {
      id
      userId
    }
  }
}

query allVibboGroups($organizationSlug: OrganizationID!, $limit: Int) {
  allVibboGroups(organizationId: $organizationSlug, limit: $limit) {
    ...VibboGroups
  }
}
fragment VibboGroups on VibboGroup {
  id
  name
  description
  slug
  type
  imageUrl
  isPrivateGroup
  memberCount
  createdBy {
    id
    userId
    name
    profilePhotoUrl
    jobTitle
  }
  organization {
    isCluster
    id
    name
  }
  viewerIsAdmin
  viewerIsMember
}

query apartmentFinances($organizationSlug: OrganizationID!, $apartmentNumber: Int!) {
  apartmentFinances(
    organizationId: $organizationSlug
    objectNumber: $apartmentNumber
  ) {
    invoices {
      invoiceId
      kid
      amount
      remainingAmount
      paymentDate
      bankAccountNumber
      paymentStatus
      reminderStatus
      type
      pdfDownloadUrl
    }
    amountDue
  }
}

query bookingByToken($jwt: String!) {
  getBookingByToken(jwt: $jwt) {
    ...BookingReceipt
  }
}
fragment BookingReceipt on BookingReceipt {
  id
  from
  description
  to
  external
  confirmedAt
  status
  price
  surchargeAmount
  surchargeDescription
  priceBreakdown {
    bookingDate
    price
  }
  calendar {
    id
    title
    reservationType
    paymentRequired
    timeFrom
    timeTo
    imageUrl
    topic {
      id
      slug
      title
      attachments {
        id
        url
        filename
        contentType
        meta {
          fileSize
          width
          height
        }
      }
    }
  }
}

query bookingDetails($id: NodeID!) {
  booking(id: $id) {
    ...BookingDetails
  }
}
fragment BookingDetails on Booking {
  id
  from
  to
  external
  description
  status
  price
  surchargeAmount
  surchargeDescription
  calendar {
    id
    title
    reservationType
    timeFrom
    timeTo
    paymentRequired
    price
    priceExtern
    priceUnit
    topic {
      id
      slug
      title
      attachments {
        id
        url
        filename
        contentType
        meta {
          fileSize
          width
          height
        }
      }
    }
  }
}

query confirmContactInfoPage {
  viewer {
    id
    changeRequest {
      email {
        id
        changeRequestId
        newEmail
      }
    }
  }
}

query entityRevision($revisionId: NodeID!) {
  revision: revisionById(id: $revisionId) {
    ...EntityRevisionWithContent
  }
}
fragment EntityRevisionWithContent on EntityRevision {
  ...EntityRevisionBase
  content
}
fragment EntityRevisionBase on EntityRevision {
  id
  updatedAt
  updatedBy {
    id
    name
  }
}

query executiveBoardMembers($organizationId: OrganizationID!) {
  getBoardMembersForExpense(organizationId: $organizationId) {
    id
    personId
    name
  }
}

query expenseDraftDefaultAccountNumberForExpensesPage($organizationId: OrganizationID!) {
  expenseDraftDefaultAccountNumber(organizationId: $organizationId)
}

query expenseDraftForExpenseRegisterForm($id: NodeID!) {
  expenseDraft(id: $id) {
    id
    amount
    category
    description
    participants {
      id
      personId
      name
    }
    recipient {
      personId
      name
      accountNumber
    }
    attachments {
      id
      previewUrl
      name
      downloadUrl
      analysis {
        status
        confidenceScore
        amount
        reason
        ocrQuality
        suspectedDuplicate
      }
    }
  }
}

query formAttachmentAnswers($formId: NodeID!, $limit: Int, $offset: Int) {
  form(id: $formId) {
    id
    attachmentAnswers(limit: $limit, offset: $offset) {
      totalCount
      nodes {
        submissionId
        submittedAt
        response
        submitter {
          userId
          name
          roles
          apartments
        }
        attachments {
          id
          filename
          url
        }
      }
    }
  }
}

query formFieldAnswers($formId: NodeID!, $fieldId: String!, $limit: Int, $offset: Int) {
  form(id: $formId) {
    id
    fieldAnswers(fieldId: $fieldId, limit: $limit, offset: $offset) {
      totalCount
      nodes {
        submissionId
        submittedAt
        response
        submitter {
          userId
          name
          roles
          apartments
        }
        attachments {
          id
          filename
          url
        }
      }
    }
  }
}

query formSubmissionCount($formId: NodeID!) {
  form(id: $formId) {
    id
    submissionCount
  }
}

query formSubmissions($formId: NodeID!, $limit: Int, $offset: Int) {
  form(id: $formId) {
    id
    title
    attachmentsEnabled
    createdAt
    fields {
      id
      value
    }
    submissionCount
    submissions(limit: $limit, offset: $offset) {
      totalCount
      nodes {
        id
        submittedAt
        authorOrganization {
          id
          name
        }
        attachments {
          id
          filename
          url
        }
        submitter {
          userId
          name
          email
          phone
          roles
          apartments
        }
        fields {
          fieldId
          fieldTitle
          response
        }
      }
    }
  }
}

query getBooking($id: NodeID!) {
  booking(id: $id) {
    id
    organization {
      id
      name
    }
  }
}

query getExternalBooking($id: ID!) {
  getExternalBooking(id: $id) {
    ...ExternalBooking
  }
}
fragment ExternalBooking on ExternalBooking {
  id
  from
  description
  to
  external
  confirmedAt
  email
  status
  firstName
  lastName
  phoneNumber
  price
  surchargeAmount
  surchargeDescription
  priceBreakdown {
    bookingDate
    price
  }
  calendar {
    id
    title
    reservationType
    paymentRequired
    timeFrom
    timeTo
    imageUrl
    topic {
      id
      slug
      title
      attachments {
        id
        url
        filename
        contentType
        meta {
          fileSize
          width
          height
        }
      }
    }
  }
}

query getThreadGroupStatus($organizationId: OrganizationID!, $threadGroupId: NodeID!) {
  getThreadGroupStatus(
    organizationId: $organizationId
    threadGroupId: $threadGroupId
  ) {
    id
    totalCount
    createdCount
  }
}

query hasMobileKeyProject($input: OrganizationID!) {
  hasMobileKeyProject(input: $input)
}

query isFeatureEnabled($name: String!, $properties: [FeatureEnabledProperties], $fallback: Boolean) {
  isFeatureEnabled(name: $name, properties: $properties, fallback: $fallback)
}

query kioskAdminMemberships {
  viewer {
    personId
    memberships {
      obosCompanyNumber
      name
      roles
    }
  }
}

query kioskUsers {
  kioskUsers {
    id
    user {
      personId
      name
    }
    memberships {
      organizationId
      organization {
        id
        name
        obosCompanyNumber
      }
      member {
        id
        roles
        kioskLoginUrl
      }
    }
  }
}

query MobileKeyLocks($input: MobileKeyLocksInput!) {
  mobileKeyLocks(input: $input) {
    unlocLockId
    name
  }
}

query myExpenseItemsForExpenseCardList($organizationId: OrganizationID!) {
  myExpenseItems(organizationId: $organizationId) {
    status
    invoiceExpenseItems {
      id
      createdAt
      amount
      category
      description
      participants {
        personId
        name
      }
      recipient {
        name
        accountNumber
      }
      statusInfo {
        status
        lastUpdatedAt
        comment {
          text
          action
          createdBy {
            id
            name
          }
          createdAt
        }
      }
      approvalStatus
      attachments {
        id
        name
        previewUrl
        downloadUrl
        analysis {
          status
          confidenceScore
          amount
          reason
          ocrQuality
          suspectedDuplicate
        }
      }
    }
  }
}

query newsComments($organizationSlug: OrganizationID!, $newsSlug: String!) {
  organization(id: $organizationSlug) {
    id
    news: newsBySlug(slug: $newsSlug) {
      id
      comments {
        ...Comment
      }
    }
  }
}
fragment Comment on Comment {
  ...CommentData
  threadId
  thread {
    ...CommentData
  }
}
fragment CommentData on Comment {
  id
  content
  anchor
  hidden
  createdBy {
    id
    userId
    name
    profilePhotoUrl
    jobTitle
  }
  authorOrganizationId
  authorOrganization {
    id
    name
  }
  authorPrimaryRole
  createdAt
  updatedAt
  deletedAt
  attachments {
    ...Attachment
  }
  ...SocialReactableListItem
}
fragment Attachment on Attachment {
  id
  filename
  url
  contentType
  meta {
    fileSize
    width
    height
  }
}
fragment SocialReactableListItem on SocialReactable {
  id
  __typename
  reactionCount(type: THUMBS_UP)
  viewerReactions
}

query newsPreviewByYear($organizationId: OrganizationID!, $filters: FindNewsFiltersInput!) {
  organization(id: $organizationId) {
    id
    news(filters: $filters) {
      ...NewsPreview
      topics {
        ...TopicPreview
      }
    }
  }
}
fragment NewsPreview on News {
  id
  title
  ingress
  slug
  isPublished
  pinned(organizationId: $organizationId)
  dateFrom
  viewerHasRead
  commentsEnabled
  commentsCount
  isClusterNews
  updatedAt
  updatedBy {
    id
    name
  }
  draft {
    meta
  }
  mainImage {
    id
    url
    meta {
      width
      height
    }
  }
  reactionCount(type: THUMBS_UP)
  organization {
    id
    slug
    name
  }
  authorOrganization {
    id
    name
    slug
  }
}
fragment TopicPreview on Topic {
  id
  slug
  title
  isPublished
  showOnDashboard(organizationId: $organizationId)
  showOnPublicOrganizationPage
  isClusterTopic
  createdFromTemplate
  draft {
    meta
  }
  organization {
    id
  }
}

query newsReadBy($organizationSlug: OrganizationID!, $newsId: NodeID!) {
  organization(id: $organizationSlug) {
    id
    organizationCode
    news: newsById(id: $newsId) {
      id
      newsReadByCount
      __typename
    }
  }
}

query newsReadByDetails($organizationSlug: OrganizationID!, $newsId: NodeID!) {
  organization(id: $organizationSlug) {
    id
    organizationCode
    hasGarages
    residents(canReadNewsId: $newsId) {
      id
      firstName
      lastName
      loggedInToVibbo
      hasEmailConsent
      hasSmsConsent
      email
      phoneNumber
      hasReadNews(newsId: $newsId)
      primaryResidentType
      residencies {
        id
        type
        apartment {
          id
          apartmentNumber
          residentialNumber
          unitNumber
          doorway
          address
          objectType
        }
      }
    }
  }
}

query notificationCenter($organizationId: OrganizationID!, $limit: Int, $after: DateTime) {
  notificationFeed(organizationId: $organizationId, limit: $limit, after: $after) {
    viewerLastViewedNotificationsAt
    items {
      id
      kind
      happenedAt
      item {
        __typename
        ... on News {
          id
          slug
          title
          ingress
        }
        ... on Topic {
          id
          slug
          title
          isClusterTopic
        }
        ... on Comment {
          id
          content
          author: createdBy {
            id
            name
            profilePhotoUrl
          }
        }
        ... on Post {
          id
          slug
          title
          body
          updatedBy {
            id
            name
            firstName
            lastName
            profilePhotoUrl
          }
          postAttachments: attachments {
            id
            url
            filename
            contentType
            meta {
              id
              width
              height
            }
          }
        }
        ... on Booking {
          id
          from
          to
          organization {
            id
            slug
            name
            isCluster
          }
          calendar {
            id
            title
            imageUrl
            topic {
              slug
              attachments {
                id
                url
                filename
                contentType
                meta {
                  id
                  width
                  height
                }
              }
            }
          }
        }
        ... on VibboEvent {
          id
          name
          description
          imageUrl
          isBoardEvent
          viewerIsAttendee
          createdAt
          slug
          dateFrom
          dateTo
        }
        ... on SocialReaction {
          id
          type
          createdBy {
            id
            name
            firstName
            profilePhotoUrl
          }
        }
        ... on VibboGroup {
          id
          slug
          name
          description
          imageUrl
          groupType: type
          memberCount
          createdBy {
            id
            name
            userId
            firstName
          }
        }
        ... on GroupPost {
          id
          slug
          body
          createdBy {
            id
            name
            firstName
            userId
          }
        }
        ... on ApartmentInvoiceNotification {
          invoiceId
          apartmentNumber
          paymentDate
          amount
        }
      }
      parent {
        __typename
        ... on News {
          id
          slug
          title
        }
        ... on Topic {
          id
          slug
          title
        }
        ... on Post {
          id
          slug
          title
        }
        ... on Comment {
          id
          content
          parent: commentParent {
            __typename
            id
            relativePath
            title
          }
        }
        ... on VibboGroup {
          id
          slug
          name
        }
      }
    }
    totalCount
  }
}

query notificationCount($organizationId: OrganizationID!, $includeNotifications: Boolean = true) {
  organization(id: $organizationId) {
    id
    threadNotificationsForViewer
    unseenActivitiesForViewer
    pendingTransferApplicationsCountForViewer
    unseenNotificationsForViewer @include(if: $includeNotifications)
  }
}

query oldestNewsDate($organizationId: OrganizationID!) {
  oldestNewsDate(organizationId: $organizationId)
}

query organizationMembers($organizationSlug: OrganizationID!) {
  organization(id: $organizationSlug) {
    id
    residents {
      id
      userId
      name
      firstName
      lastName
      isBoardMember
      profilePhotoUrl
      residencies {
        id
        apartment {
          id
          address
          objectType
          apartmentNumber
          apartmentType
        }
      }
    }
    executiveMembers(filterOBOS: true) {
      id
      name
      firstName
      lastName
      userId
      profilePhotoUrl
      jobTitle
    }
  }
  janitors(organizationId: $organizationSlug) {
    id
    name
    firstName
    lastName
    userId
    profilePhotoUrl
    jobTitle
  }
}

query pendingInvitations {
    viewer {
      id

      pendingInvitations {
        id
