  viewerReactions
}

query refetchProfilePhoto {
        viewer {
          id
          profilePhotoUrl
        }
      }

query revisionHistoryList($relatedNodeId: UnpackedNodeID!) {
  history: revisionHistoryForRelatedNodeId(relatedNodeId: $relatedNodeId) {
    ...EntityRevisionBase
  }
}
fragment EntityRevisionBase on EntityRevision {
  id
  updatedAt
  updatedBy {
    id
    name
  }
}

query searchPublicOrganizations($query: String!) {
    searchPublicOrganizations(query: $query) {
      items {
        result {
          id
          name
          slug
          obosCompanyNumber

          primaryAddress {
            address
          }

          addresses {
            address
          }
        }
      }
    }
  }

query topicReadByCount($organizationSlug: OrganizationID!, $topicSlug: String!) {
  organization(id: $organizationSlug) {
    id
    topic: topicBySlug(slug: $topicSlug) {
      id
      topicReadByCount
      __typename
    }
  }
}

query topicReadByDetails($organizationSlug: OrganizationID!, $topicId: NodeID!) {
  organization(id: $organizationSlug) {
    id
    organizationCode
    residents {
      id
      firstName
      lastName
      loggedInToVibbo
      email
      phoneNumber
      hasReadTopic(topicId: $topicId)
      primaryResidentType
      residencies {
        id
        type
        apartment {
          id
          apartmentNumber
          residentialNumber
          unitNumber
          doorway
          address
          objectType
        }
      }
    }
  }
}

query vibboAboutOrganizationQuery($organizationSlug: OrganizationID!) {
    organization(id: $organizationSlug) {
      id
      slug
      name
      obosCompanyNumber
      organizationNumber
      boardEmail
      boardPhoneNumber
      organizationCodeDescription
      neighborhoodProfileUrl
      insurance {
        policy {
          insuranceCompanyName
          policyNumber
        }
      }
      documents {
        downloadUrl
        year
        filename
        changedAt
        assemblyDate
        category {
          code
          name
        }
      }
      clusters {
        id
        name
        organizations(skipMembership: true) {
          id
          name
        }
      }
      statistics {
        id
        buildings {
          apartmentsCount
          buildingTypes {
            description
          }
        }
      }
    }
  }

query vibboActivityPage($organizationSlug: OrganizationID!) {
  organization(id: $organizationSlug) {
    id
  }
}

query vibboActivityStream($organizationId: OrganizationID!, $limit: Int, $after: DateTime, $filter: OrganizationActivityFilter) {
  stream: activityInOrganization(
    organizationId: $organizationId
    limit: $limit
    after: $after
    filter: $filter
  ) {
    viewerLastViewedActivityAt
    items {
      id
      kind
      happenedAt
      item {
        __typename
        ... on News {
          id
          slug
          title
          ingress
          pinned
          topics {
            id
            isClusterTopic
            title
          }
          isClusterNews
          mainImage {
            id
            url
            filename
            meta {
              id
              width
              height
            }
          }
          authorOrganization {
            id
            name
          }
          organization {
            id
            slug
            name
            isCluster
          }
          commentsCount
          thumbsUpCount: reactionCount(type: THUMBS_UP)
        }
        ... on Topic {
          id
          slug
          title
          ingress
          mainImage {
            id
            url
            filename
            meta {
              id
              width
              height
            }
          }
          organization {
            id
            slug
            name
            isCluster
          }
        }
        ... on Post {
          id
          slug
          title
          body
          category {
            id
            label
          }
          updatedBy {
            id
            name
            firstName
          }
          organization {
            id
            slug
            name
            isCluster
          }
          postAttachments: attachments {
            id
            url
            filename
            contentType
            meta {
              id
              width
              height
            }
          }
          commentsCount
          thumbsUpCount: reactionCount(type: THUMBS_UP)
        }
        ... on Comment {
          id
          content
          author: createdBy {
            id
            name
          }
          thumbsUpCount: reactionCount(type: THUMBS_UP)
        }
        ... on VibboEvent {
          id
          name
          description
          imageUrl
          isBoardEvent
          attendeeCount
          viewerIsAttendee
          createdAt
          slug
          dateFrom
          createdBy {
            id
            name
            firstName
            userId
          }
          organization {
            id
            slug
            name
            isCluster
          }
        }
        ... on VibboGroup {
          id
          slug
          name
          description
          imageUrl
          memberCount
          createdBy {
            id
            name
            userId
            firstName
          }
          organization {
            id
            slug
            name
            isCluster
          }
        }
        ... on GroupPost {
          id
          slug
          body
          createdBy {
            id
            name
            firstName
            userId
          }
          organization {
            id
            slug
            name
            isCluster
          }
        }
      }
      parent {
        __typename
        ... on News {
          id
          slug
          title
        }
        ... on Post {
          id
          slug
          title
          organization {
            id
            slug
            name
            isCluster
          }
        }
        ... on Topic {
          id
          slug
          title
        }
        ... on VibboEvent {
          id
          slug
          name
        }
        ... on VibboGroup {
          id
          slug
          name
        }
        ... on GroupPost {
          id
          slug
          url
          group {
            id
            name
            slug
          }
        }
      }
    }
    totalCount
  }
  pinnedNews: pinnedNewsActivityInOrganization(organizationId: $organizationId) {
    viewerLastViewedActivityAt
    items {
      id
      kind
      happenedAt
      item {
        __typename
        ... on News {
          id
          slug
          title
          ingress
          pinned(organizationId: $organizationId)
          topics {
            id
            isClusterTopic
            title
          }
          isClusterNews
          mainImage {
            id
            url
            filename
            meta {
              id
              width
              height
            }
          }
          authorOrganization {
            id
            name
          }
          organization {
            id
            slug
            name
            isCluster
          }
          commentsCount
          thumbsUpCount: reactionCount(type: THUMBS_UP)
        }
      }
    }
  }
}

query vibboAdministrateReservations($organizationSlug: OrganizationID!, $page: Int!, $pageSize: Int!, $sortBy: CalendarSortBy, $sortDirection: SortDirection, $searchTerm: String, $from: DateTime, $to: DateTime, $calendarId: NodeID, $statusFilter: BookingDashboardStatusFilter) {
  getBookingsForOrganization(
    organizationId: $organizationSlug
    page: $page
    pageSize: $pageSize
    sortBy: $sortBy
    sortDirection: $sortDirection
    searchTerm: $searchTerm
    from: $from
    to: $to
    calendarId: $calendarId
    statusFilter: $statusFilter
  ) {
    bookings {
      ...BookingAdministrationDetails
    }
    pagination {
      total
      page
      pageSize
      pageCount
      hasMore
    }
  }
}
fragment BookingAdministrationDetails on Booking {
  ...Booking
  isDeleted
  organization {
    id
    name
  }
  calendar {
    ...Calendar
  }
}
fragment Booking on Booking {
  id
  from
  description
  to
  privateBooking
  external
  confirmedAt
  email
  status
  price
